import{_ as t}from"./chunks/console-applications.BAb8jNxE.js";import{_ as a,o as i,c as n,a3 as o}from"./chunks/framework.DhF4LrUq.js";const w=JSON.parse('{"title":"Register and manage applications","description":"Register and manage applications - the registry, ownership scope, authorized tenants, and the archive lifecycle.","frontmatter":{"description":"Register and manage applications - the registry, ownership scope, authorized tenants, and the archive lifecycle."},"headers":[],"relativePath":"how-to/console/apps.md","filePath":"how-to/console/apps.md"}'),r={name:"how-to/console/apps.md"};function s(l,e,p,h,c,d){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="register-and-manage-applications" tabindex="-1">Register and manage applications <a class="header-anchor" href="#register-and-manage-applications" aria-label="Permalink to &quot;Register and manage applications&quot;">​</a></h1><p>Applications are the products you distribute. The <strong>Applications</strong> screen registers them and pins the store identifiers that later artifact validation checks every upload against.</p><p><img src="'+t+'" alt="The Applications screen"></p><p>The ownership model — tenant-owned versus organization-shared — is explained in <a href="/shipperdog/snapshot/get-started/concepts">core concepts</a>.</p><h2 id="two-views-of-the-registry" tabindex="-1">Two views of the registry <a class="header-anchor" href="#two-views-of-the-registry" aria-label="Permalink to &quot;Two views of the registry&quot;">​</a></h2><p>The listing-scope toggle above the grid switches between:</p><ul><li><strong>All applications</strong> — every application in your organization, including shared applications no tenant is authorized for yet. This is the administrator&#39;s view.</li><li><strong>By tenant</strong> — the <strong>Tenant (effective visibility)</strong> picker comes alive; pick a tenant and see exactly what it can see: its own applications plus the shared ones authorized for it. This is the honest answer to &quot;what does Acme get?&quot;</li></ul><h2 id="register-an-application" tabindex="-1">Register an application <a class="header-anchor" href="#register-an-application" aria-label="Permalink to &quot;Register an application&quot;">​</a></h2><ol><li><p>Open <strong>Applications</strong> and click <strong>New application</strong>.</p></li><li><p>Fill in the dialog:</p><ul><li><strong>Name</strong> and an optional <strong>Description</strong>.</li><li><strong>Platforms</strong> — iOS, Android, or both. Pick at least one.</li><li><strong>Bundle ID (iOS)</strong> — required when iOS is selected (for example <code>com.northwind.fieldservice</code>).</li><li><strong>Package name (Android)</strong> — required when Android is selected.</li><li><strong>Ownership</strong> — <strong>Tenant-owned</strong> (pick the owner tenant) or <strong>Organization-shared</strong>. A tenant-owned app belongs to one tenant; a shared app is offered to tenants through explicit authorizations.</li></ul></li><li><p>Click <strong>Create</strong>. The application appears in the grid with its status <strong>Active</strong>.</p></li></ol><h2 id="edit-and-change-ownership" tabindex="-1">Edit and change ownership <a class="header-anchor" href="#edit-and-change-ownership" aria-label="Permalink to &quot;Edit and change ownership&quot;">​</a></h2><ol><li><p>Open the application (the <strong>View</strong> action) and click <strong>Edit</strong>.</p></li><li><p>Names, descriptions, and per-platform identifiers edit freely — the dialog validates the same rules as creation.</p></li><li><p>Changing <strong>Ownership</strong> is an audited transition:</p><ul><li>Converting to <strong>organization-shared</strong> takes effect immediately.</li><li>Converting a shared application to <strong>tenant-owned</strong> asks for the new owner tenant — and is refused while ACTIVE tenant authorizations remain. Revoke them first.</li></ul></li></ol><h2 id="authorize-tenants-for-a-shared-application" tabindex="-1">Authorize tenants for a shared application <a class="header-anchor" href="#authorize-tenants-for-a-shared-application" aria-label="Permalink to &quot;Authorize tenants for a shared application&quot;">​</a></h2><p>On a shared application&#39;s page, the <strong>Authorized tenants</strong> section decides which tenants receive it:</p><ol><li>Click <strong>Authorize tenant</strong>.</li><li>Pick the tenant; an optional <strong>reason</strong> records why.</li><li><strong>Revoke</strong> on a row ends the authorization (confirm with an optional reason).</li></ol><p>Until a tenant is authorized, a shared application simply does not exist for that tenant&#39;s testers — no partial visibility.</p><h2 id="archive-and-unarchive" tabindex="-1">Archive and unarchive <a class="header-anchor" href="#archive-and-unarchive" aria-label="Permalink to &quot;Archive and unarchive&quot;">​</a></h2><p><strong>Archive</strong> on the application page is reversible: the application stays readable with its audit history but accepts no new versions or artifacts. Confirm in the dialog naming the application; unarchive from the same place when it returns.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/versions-and-tags">versions and tags</a> · <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a> · <a href="/shipperdog/snapshot/roles/app-owner">app-owner quickstart</a></p>',18)])])}const f=a(r,[["render",s]]);export{w as __pageData,f as default};
